-- ============================================================================
-- DEV/DEMO SEED — Dwarka, New Delhi. GENERATED by db/gen_dwarka_seed.py.
-- REALISTIC per-approach cameras: one camera per road arriving at each
-- junction, offset ~25m back and facing incoming traffic. Links are through-
-- movements (arrival at J from I -> arrival at K from J). OSRM-routed.
-- Re-runnable; TRUNCATEs the network — STOP the pipeline workers first.
-- ============================================================================
BEGIN;
TRUNCATE cameras, roads, plates, camera_links, sightings, blacklist_entries,
         alerts, camera_metrics_5m, traffic_metrics_5m RESTART IDENTITY CASCADE;

